from openpyxl import load_workbook
for data_only in (False, True):
    wb = load_workbook('budget.xlsx', data_only=data_only)
    ws = wb['Budget']
    print('=== data_only =', data_only, '===')
    for row in ws.iter_rows(min_row=1, max_row=25, max_col=3):
        for c in row:
            if c.value is not None:
                print(c.coordinate, repr(c.value))
